import fs from 'fs';
import os from 'os';
import path from 'path';

export type GitCliConfig = {
  aiProvider?: string;
  aiModel?: string;
  aiBaseUrl?: string;
  tokens?: Record<string, string>;
  linkedRepos?: string[];
  pluginPolicies?: {
    allow?: string[];
    deny?: string[];
  };
  notifications?: {
    slackWebhook?: string;
    discordWebhook?: string;
  };
  cloudSync?: {
    enabled: boolean;
    endpoint?: string;
    apiKey?: string;
    headers?: Record<string, string>;
  };
};

const baseDir = path.join(os.homedir(), '.gitcli');
const configPath = path.join(baseDir, 'config.json');
const notesPath = path.join(baseDir, 'notes.json');
const historyPath = path.join(baseDir, 'history.json');
const pluginDir = path.join(baseDir, 'plugins');

function ensureBase() {
  if (!fs.existsSync(baseDir)) fs.mkdirSync(baseDir, { recursive: true });
  if (!fs.existsSync(pluginDir)) fs.mkdirSync(pluginDir, { recursive: true });
}

function validateConfig(cfg: GitCliConfig): GitCliConfig {
  const safe = { ...cfg };
  if (safe.aiProvider && typeof safe.aiProvider !== 'string') delete safe.aiProvider;
  if (safe.aiModel && typeof safe.aiModel !== 'string') delete safe.aiModel;
  if (safe.aiBaseUrl && typeof safe.aiBaseUrl !== 'string') delete safe.aiBaseUrl;
  if (safe.tokens && typeof safe.tokens !== 'object') delete safe.tokens;
  if (safe.cloudSync && typeof safe.cloudSync !== 'object') delete safe.cloudSync;
  if (safe.pluginPolicies && typeof safe.pluginPolicies !== 'object') delete safe.pluginPolicies;
  return safe;
}

export function readConfig(): GitCliConfig {
  ensureBase();
  if (!fs.existsSync(configPath)) return { cloudSync: { enabled: false } };
  try {
    const raw = fs.readFileSync(configPath, 'utf8');
    const parsed = JSON.parse(raw);
    return validateConfig(parsed);
  } catch {
    return { cloudSync: { enabled: false } };
  }
}

export function writeConfig(config: GitCliConfig) {
  ensureBase();
  fs.writeFileSync(configPath, JSON.stringify(config, null, 2));
}

export function getHistoryStorePath() {
  ensureBase();
  return historyPath;
}

export function getNotesPath() {
  ensureBase();
  if (!fs.existsSync(notesPath)) fs.writeFileSync(notesPath, JSON.stringify({ commits: {} }, null, 2));
  return notesPath;
}

export function getPluginDir() {
  ensureBase();
  return pluginDir;
}

export function getConfigPath() {
  ensureBase();
  return configPath;
}
